        if(ph >= 3) sw.push([24, +(want + sd*0.9).toFixed(3)]);
        X.act = { k, t:0, id, x:S.x, z:S.z, R:10, hw:1.05, sp:1.1, sw }; X.cd.edge = ph >= 3 ? 22 : 28; X.face = want; X.vx = X.vz = 0;
