      let k = null, lk = 1e9;
      if(ph >= 4 && X.cd.requiem <= 0) k = 'requiem';
      else if(X.cd.slam <= 0 && X.lastK !== 'slam') k = 'slam';
      else for(const m in MIN){ if(ph < MIN[m] || X.cd[m] > 0) continue; const l = X.last[m] || 0; if(l < lk){ lk = l; k = m; } }
