  if(X.gap > 0) X.gap--;

  if(ph > X.ph){ X.ph = ph; X.act = { k:'rise', t:0 }; A.fx('gqx_rise', { x:R2(S.x), z:R2(S.z), p:ph });
    inA.forEach(p => { if(D(p, S.x, S.z) < 7) A.push(p.k, S.x, S.z, 5); });
    if(ph === 2) X.cd.bliz = 25; if(ph >= 4) X.cd.zero = 30; }

