        const nx = e.x + (dx/len) * _sp, nz = e.z + (dz/len) * _sp; // 1.6 = server tick scale
        if (zoneName === 'void') { if (_vwWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_vwWalkable(nx, e.z)) e.x = nx; else if (_vwWalkable(e.x, nz)) e.z = nz; }   // a640 — void pits
        else if (zoneName === 'sunken_sands') { if (_snWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_snWalkable(nx, e.z)) e.x = nx; else if (_snWalkable(e.x, nz)) e.z = nz; }   // a655 — dunes, monuments, sinkholes
        else if (zoneName === 'ancient') { if (_anWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_anWalkable(nx, e.z)) e.x = nx; else if (_anWalkable(e.x, nz)) e.z = nz; }   // a653 — ruins, trees, water
        else if (zoneName === 'necropolis') { if (_npWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_npWalkable(nx, e.z)) e.x = nx; else if (_npWalkable(e.x, nz)) e.z = nz; }   // a652 — the city's walls, canal, pillars
        else if (zoneName === 'frostveil') { if (_fvWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_fvWalkable(nx, e.z)) e.x = nx; else if (_fvWalkable(e.x, nz)) e.z = nz; }   // a651 — glaciers, open water, rocks, pines
        else if (zoneName === 'cemetery') { if (_cmWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_cmWalkable(nx, e.z)) e.x = nx; else if (_cmWalkable(e.x, nz)) e.z = nz; }   // a650 — graves + crypts
        else if (zoneName === 'fungal') { if (_fgWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_fgWalkable(nx, e.z)) e.x = nx; else if (_fgWalkable(e.x, nz)) e.z = nz; }   // a649 — fungal stems + mounds
        else if (zoneName === 'the_reach') { if (_reWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_reWalkable(nx, e.z)) e.x = nx; else if (_reWalkable(e.x, nz)) e.z = nz; }   // a665 — the cliffs, the rifts, the dead works
        else if (zoneName === 'forge') { if (_foWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_foWalkable(nx, e.z)) e.x = nx; else if (_foWalkable(e.x, nz)) e.z = nz; }   // a668 — the works, the lava, the walls
        else if (zoneName === 'dragonlair') { if (_dlWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_dlWalkable(nx, e.z)) e.x = nx; else if (_dlWalkable(e.x, nz)) e.z = nz; }   // a669 — the caldera wall, the volcano, the lava, the nest's rim
        else if (zoneName === 'veiled_sanctuary') { if (_vsWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_vsWalkable(nx, e.z)) e.x = nx; else if (_vsWalkable(e.x, nz)) e.z = nz; }   // a670 — the cathedral's walls, columns and pews
        else if (zoneName === 'caves_of_despair') { if (_cdWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_cdWalkable(nx, e.z)) e.x = nx; else if (_cdWalkable(e.x, nz)) e.z = nz; }   // a671 — the maze's rock
        else if (zoneName === 'xulcan') { if (_xuWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_xuWalkable(nx, e.z)) e.x = nx; else if (_xuWalkable(e.x, nz)) e.z = nz; }   // a664 — the golden towers, the outpost walls
        else if (zoneName === 'wyvernwastes') { if (_wwWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_wwWalkable(nx, e.z)) e.x = nx; else if (_wwWalkable(e.x, nz)) e.z = nz; }   // a663 — the ranges, crevasses, nest rims and crags
        else if (zoneName === 'neon_hollow') { if (_nhWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_nhWalkable(nx, e.z)) e.x = nx; else if (_nhWalkable(e.x, nz)) e.z = nz; }   // a661 — the city's buildings, wall and monorail pylons
        else if (zoneName === 'xeron') { if (_xrWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_xrWalkable(nx, e.z)) e.x = nx; else if (_xrWalkable(e.x, nz)) e.z = nz; }   // a660 — the towers and the edge of the disc
        else if (zoneName === 'xumen_fortress') { if (_xfWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_xfWalkable(nx, e.z)) e.x = nx; else if (_xfWalkable(e.x, nz)) e.z = nz; }   // a658 — the fortress walls, hangars, cradles, tanks
        else if (zoneName === 'xumen') { if (_xcWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_xcWalkable(nx, e.z)) e.x = nx; else if (_xcWalkable(e.x, nz)) e.z = nz; }   // a648 — the capital's buildings
        else if (zoneName === 'void_citadel') { if (_vcWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_vcWalkable(nx, e.z)) e.x = nx; else if (_vcWalkable(e.x, nz)) e.z = nz; }   // a647 — citadel walls + void
        else if (zoneName === 'riftvale') { if (_rvWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_rvWalkable(nx, e.z)) e.x = nx; else if (_rvWalkable(e.x, nz)) e.z = nz; }   // a645 — rift vale void
        else if (zoneName === 'citadel') { if (_ctWalkable(nx, nz)) { e.x = nx; e.z = nz; } else if (_ctWalkable(nx, e.z)) e.x = nx; else if (_ctWalkable(e.x, nz)) e.z = nz; }   // a641 — citadel walls
        else if (!_mz || !e2ConvMazeWall(_mz, nx, nz, TILE)) { e.x = nx; e.z = nz; }
        else if (!e2ConvMazeWall(_mz, nx, e.z, TILE)) e.x = nx;      // slide along the wall
        else if (!e2ConvMazeWall(_mz, e.x, nz, TILE)) e.z = nz;
