          e._roll=(e._roll||0)+1; if(dd<9 && e._roll>=25){ e._roll=0; mv(pr*strafe,pq*strafe,MSs*9); broadcastToZone(game.id,zoneName,{type:'sv_fx',vt:'sd_poof',zone:zoneName,ex:+e.x.toFixed(2),ez:+e.z.toFixed(2),col:0x6cff7a,n:5}); }
