    if(e._spN > 0){ e._spN--; if(e._spN % 2 === 0){ for(let k=0;k<4;k++) P.shoot(e._spA + k*PI/2, (k % 2) ? CRIM : LAV, 0.35, 1, 0); e._spA += 0.38; } }
