// a527 — spawn a server-owned SD projectile (server resolves the hit; client renders the flyer).
// a529 — telegraphed ground strike (recon ping / mortar / airstrike): warning ring now, AoE later.
function _pmTelegraph(game, zoneName, e, tx, tz, fuseTicks, radius, dmg, col){
  if(!game._sdGeyser) game._sdGeyser = [];
  game._sdGeyser.push({ zone:zoneName, x:tx, z:tz, fuse:fuseTicks, dmg:dmg, eid:e.id, col:col, radius:radius });
  broadcastToZone(game.id, zoneName, { type:'sv_fx', vt:'sd_geyser_warn', zone:zoneName, ex:+tx.toFixed(2), ez:+tz.toFixed(2), col:col });
}
// a529 — instant shockwave + AoE (shock stomp / spectral wail / lunge impact).
function _pmShock(game, zoneName, e, cx, cz, radius, dmg, col, players, send, slow, slowDur){
  broadcastToZone(game.id, zoneName, { type:'sv_fx', vt:'sd_shock', zone:zoneName, ex:+cx.toFixed(2), ez:+cz.toFixed(2), col:col, r:radius });
  if(dmg>0){ players.forEach((p, ws)=>{ if(p.gameId!==game.id || p.zone!==zoneName || p.x===undefined) return;
    const ddx=p.x-cx, ddz=p.z-cz; if(ddx*ddx+ddz*ddz < radius*radius){
      send(ws, { type:'sv_enemy_attack', eid:e.id, dmg:dmg, ex:+cx.toFixed(2), ez:+cz.toFixed(2), zone:zoneName });
      if(slow) send(ws, { type:'sv_player_fx', zone:zoneName, eff:'slow', slow:slow, root:(slowDur||1200) });
    } }); }
}
function _sdSpawnProj(game, zoneName, e, ang, col, dmg, kind, status, statusDur){
  if(!game._sdProj) game._sdProj = [];
  game._sdProj.push({ zone:zoneName, x:e.x, z:e.z, vx:Math.sin(ang)*1.4, vz:Math.cos(ang)*1.4, dmg:dmg, status:status||null, statusDur:statusDur||0, life:10, eid:e.id });
  broadcastToZone(game.id, zoneName, { type:'sv_fx', vt:'sd_proj', zone:zoneName, ex:+e.x.toFixed(2), ez:+e.z.toFixed(2), ang:+ang.toFixed(3), col:col, kind:kind });
}

// Full snapshot for a player entering a zone
function sendZoneSnapshot(ws, game, zoneName) {
  const zone = getOrCreateZone(game, zoneName);
  const ids=[], xs=[], zs=[], hps=[], maxhps=[], types=[], acts=[];
  zone.enemies.forEach(e => {
    ids.push(e.id);
    xs.push(+e.x.toFixed(2));
    zs.push(+e.z.toFixed(2));
    hps.push(e.hp);
    maxhps.push(e.maxHp);
    types.push(e.type);
    acts.push(e.active ? 1 : 0);
  });
  const activeCount = acts.filter(a=>a===1).length;
  console.log(`[sendZoneSnapshot] zone=${zoneName} total=${ids.length} active=${activeCount}`);
  send(ws, { type:'sv_zone_snapshot', zone:zoneName, ids, xs, zs, hps, maxhps, types, acts });
  // a146 — also send the active world boss state if one is alive in this zone
  if (game.worldBoss && game.worldBoss.spawned && game.worldBoss.zone === zoneName) {
    const wb = game.worldBoss;
    send(ws, {
      type: 'sv_worldboss_snapshot',
      id: wb.id,
      name: wb.name,
      zone: wb.zone,
      x: +wb.x.toFixed(2),
      z: +wb.z.toFixed(2),
      hp: wb.hp,
      maxHp: wb.maxHp,
      phase: wb.phase,
      color: wb.color,
      lootTier: wb.lootTier,
    });
  }
}

// ══════════════════════════════════════════════════════════
// GLOBAL GAME LOOP — 10Hz
// ══════════════════════════════════════════════════════════
let _rosterTick = 0;   // a578
setInterval(() => {
  games.forEach(game => {
    // Tick as soon as a game exists — zones are pre-populated, enemies need ticking from start
    if (game.players.length > 0) tickGame(game);
  });
  if (++_rosterTick % 10 === 0) { try { _broadcastPartyRosters(); } catch(e){} }   // a578 — 1Hz
}, 100);

// ══════════════════════════════════════════════════════════
// LOBBY HELPERS (unchanged from original)
// ══════════════════════════════════════════════════════════

function broadcast(data, exclude=null){
  const msg = JSON.stringify(data);
  wss.clients.forEach(client => {
    if(client !== exclude && client.readyState === 1) client.send(msg);
  });
}
function getPlayerNames(){ return [...players.values()].filter(p=>p.name).map(p=>p.name); }
// v93.0-a66 — richer payload: {name, level, cls, raceName} per player.
// Defaults are sane for clients who haven't sent the new fields yet (old client).
// a596 — character portraits for the lobby list. Clients send a small image (~2-4 KB);
//   the list itself only carries a version number, and clients fetch the images they lack.
let _portraitSeq = 0;
function _cleanPortrait(s){
  if (typeof s !== 'string' || s.length > 24000) return null;
  const m = /^data:image\/(png|webp|jpeg);base64,([A-Za-z0-9+\/=]+)$/.exec(s);
  return m ? s : null;
}
function getPlayerSummary(){
  return [...players.values()].filter(p=>p.name).map(p=>({
    name: p.name,
    pv: p.portrait ? (p.pv || 0) : 0,   // a596 — portrait version (0 = none)
    level: (typeof p.level === 'number') ? p.level : 1,
    cls: p.cls || 'Warrior',
    raceName: p.raceName || 'Xu',
    asc: (typeof p.asc === 'number') ? p.asc : 0,   // v93.0-a256 — ascendancy level
    guildTag: _serverGuildTag(p.name)               // v93.0-a258 — live, server-authoritative (was p.guildTag, always null)
  }));
}
function broadcastPlayerList(){ broadcast({ type:'player_list', players:getPlayerSummary() }); }
function sendGameList(ws){
  const list = [...games.values()].filter(g => !g._pausedAt).map(g => ({   // a580 — paused games are private
    id:g.id, name:g.name, host:g.host, hostPeer:g.hostPeer,
    zone:g.zone, players:g.players.length, max:g.maxPlayers, hasPass:!!g.password
  }));
  send(ws, { type:'game_list', games:list });
}
function broadcastGameList(){ broadcast({ type:'game_list_update' }); }

// ═══════════════════════════════════════════════════════════════════════════════
// a580 — PRESENCE TUNNEL. Players used to see each other through WebRTC relayed by
//   the host's browser — which needed a free public TURN relay and PeerJS's public
//   signaling server to work at all, and which died with the host. Now the game's
//   existing peer protocol is carried by this server instead: the host is still the
//   host (it keeps its authority over world events and relaying), every message type
//   is unchanged, and only the wire is different. Everyone already holds a working
//   WebSocket to this server, so no NAT traversal is needed.
//
//   Traffic is BATCHED: each client sends one frame every ~50ms holding everything
//   it has queued, and this forwards each recipient's share as one frame. Peer state
//   runs at 20Hz per player, so unbatched a four-player host would push ~180
//   messages a second — far past the 30/s game-traffic limit, which is why tunnel
//   frames have their own budget.
//
//   When the host leaves, the game is handed to the next player instead of deleted:
//   before, a host disconnecting deleted the game outright, which stopped the world
//   ticking for everyone still in it.
// ═══════════════════════════════════════════════════════════════════════════════
const wsByPid = new Map();
const _TUN_HEAD = '{"type":"sv_tun_b",';   // how every tunnel frame begins (client sends type first)
const TUN_FRAMES_PER_SEC = 40, TUN_FRAME_BURST = 80, TUN_MSGS_PER_FRAME = 64;
function _gamePlayers(g){                      // [{pid, name, ws}] in join order, one per connection
  const out = [], seen = new Set();
  g.players.forEach(n => {
    players.forEach((p, w) => {
      if (p.gameId === g.id && p.name === n && w.readyState === 1 && !seen.has(p.pid)) {
        seen.add(p.pid); out.push({ pid:p.pid, name:p.name, ws:w });
      }
    });
  });
  return out;
}
function _tunOnFrame(ws, raw){
  const now = Date.now();
  if (ws._tunTokens === undefined) { ws._tunTokens = TUN_FRAME_BURST; ws._tunLast = now; }
  ws._tunTokens = Math.min(TUN_FRAME_BURST, ws._tunTokens + (now - ws._tunLast) * (TUN_FRAMES_PER_SEC / 1000));
  ws._tunLast = now;
  if (ws._tunTokens < 1) return;
  ws._tunTokens -= 1;
  let d; try { d = JSON.parse(raw); } catch(e){ return; }
  const me = players.get(ws);
  if (!me || !me.gameId || !Array.isArray(d.b)) return;
  const g = games.get(me.gameId);
  if (!g || !g.tun) return;
  const out = new Map();                       // recipient pid -> [msgs]
  for (const item of d.b.slice(0, TUN_MSGS_PER_FRAME)) {
    if (!Array.isArray(item) || item.length !== 2) continue;
    const to = item[0] | 0;
    const tw = wsByPid.get(to);
    if (!tw || tw === ws) continue;
    const tp = players.get(tw);
    if (!tp || tp.gameId !== me.gameId) continue;   // only within your own game
    if (!out.has(to)) out.set(to, []);
    out.get(to).push(item[1]);
  }
  out.forEach((msgs, to) => {
    const tw = wsByPid.get(to);
    if (tw && tw.readyState === 1) tw.send(JSON.stringify({ type:'sv_tun_b', from:me.pid, b:msgs }));
  });
}
// ═══════════════════════════════════════════════════════════════════════════════
// a582 — GOLD AUDIT (stage 1 of server-owned gold). SHADOW MODE: this observes and
//   records; it never changes or refuses anyone's gold. The client reports every gold
//   change, attributed to the function that made it, and the server keeps a running
//   copy per character, seeded from the stored save. Anything it can't account for is
//   appended to econ_audit.log:
//     unknown_source  a gold change from a function not in ECON_SOURCES (a source we
//                     haven't catalogued yet — or a modified client)
//     unattributed    the client's gold, or a saved gold figure, differs from what the
//                     reported changes add up to (a save edited outside the game)
//     load_mismatch   a character loaded with different gold than the server holds
//   Every gold source has to read clean here before stage 3 starts enforcing anything.
//   Run econ_report.js to read the log.
// ═══════════════════════════════════════════════════════════════════════════════
const ECON_LOG = path.join(DATA_DIR, 'econ_audit.log');
const ECON_SOURCES = {
  // income
  kill:'kill', killEnemy:'kill', killBoss:'boss', onRareKill:'rare', _worldBossOnDeath:'worldboss',
  doSell:'sell', _invQuickSell:'sell', sellAllJunk:'sell', _bulkSellByPredicate:'sell',
  turnInQuest:'quest', claimBounty:'bounty', grantDailyReward:'daily', _apexCompleteTrial:'trial',
  checkLevelUp:'levelcap', updatePlayer:'pickup', _mpOnData:'party', _removeTutorialDummy:'tutorial',
  vaultGoldWithdraw:'vault',
  // spending
  doBuy:'buy', doUpgrade:'upgrade', buySkill:'skill', upgradeSkill:'skill', vaultGoldDeposit:'vault',
  guild:'guild', playerDie:'death',
  // both
  tradeExecute:'trade',
  _carBuy:'skycar',   // a583
  _mechBuy:'mech',    // a617
};
const econLedger = new Map();      // save key -> { gold, src:{cat:{sum,n}}, touched }
function _econLog(o){
  try {
    o.at = new Date().toISOString();
    fs.appendFile(ECON_LOG, JSON.stringify(o) + '\n', () => {});
    fs.stat(ECON_LOG, (e, st) => { if (!e && st.size > 5 * 1024 * 1024) fs.rename(ECON_LOG, ECON_LOG + '.1', () => {}); });
  } catch(e){}
}
function _econL(key){
  let L = econLedger.get(key);
  if (!L) {
    const sv = cloudSaves[key];
    L = { gold: (sv && typeof sv.gold === 'number') ? sv.gold : null, src:{}, touched:false };
    econLedger.set(key, L);
  }
  return L;
}
function _econOnReport(data){
  const key = getSaveKey(data.n, data.r, data.c);
  if (!key) return;
  const L = _econL(key);
  L.touched = true;
  if (typeof data.base === 'number') {
    if (L.gold !== null && Math.round(L.gold) !== Math.round(data.base))
      _econLog({ t:'load_mismatch', key, server:L.gold, client:data.base, d:data.base - L.gold });
    L.gold = data.base;
  }
  let sum = 0;
  (Array.isArray(data.ev) ? data.ev : []).slice(0, 100).forEach(e => {
    if (!Array.isArray(e)) return;
    const s = String(e[0]).slice(0, 60), d = +e[1] || 0, n = e[2] | 0;
    const cat = ECON_SOURCES[s] || ('unknown:' + s);
    const S = L.src[cat] || (L.src[cat] = { sum:0, n:0 });
    S.sum += d; S.n += n;
    if (!ECON_SOURCES[s]) _econLog({ t:'unknown_source', key, src:s, d, n });
    sum += d;
  });
  if (L.gold === null) L.gold = (typeof data.g === 'number') ? data.g - sum : 0;   // first sight: anchor on the client
  L.gold += sum;
  if (typeof data.g === 'number' && Math.round(data.g) !== Math.round(L.gold)) {
    _econLog({ t:'unattributed', key, where:'live', expected:L.gold, client:data.g, d:data.g - L.gold });
    L.gold = data.g;
  }
}
// a save is compared against the running copy, then (shadow mode) still accepted as-is
function _econOnSave(key, incoming){
  const L = econLedger.get(key);
  if (!L || typeof incoming.gold !== 'number') return;
  if (L.gold !== null && Math.round(L.gold) !== Math.round(incoming.gold))
    _econLog({ t:'unattributed', key, where:'save', expected:L.gold, client:incoming.gold, d:incoming.gold - L.gold });
  L.gold = incoming.gold;
}
// every ten minutes, a per-source summary for each character that was active
setInterval(() => {
  econLedger.forEach((L, key) => { if (L.touched) { _econLog({ t:'summary', key, gold:L.gold, src:L.src }); L.touched = false; L.src = {}; } });
}, 10 * 60 * 1000);

// ═══════════════════════════════════════════════════════════════════════════════
// a605 — HP AUDIT (stage 1 of server-owned health). SHADOW MODE: this observes and
//   records; it never changes anyone's health or refuses anything. Every player now has
//   a health record on the server (player.hpa: health, max health, level, defence and the
//   share of a raw hit that lands for them). The client reports every health change,
//   attributed to the function that made it, every 2 seconds. The server also counts
//   every hit IT sends (sv_enemy_attack, see send()) and compares that with what landed.
//   Written to hp_audit.log, with flags also printed to the console (Railway logs):
//     no_damage_landed  the server sent real damage for a minute and none of it landed
//                       (god mode, or a client that drops sv_enemy_attack)
//     editor_heal       health set by the editor god mode in an online game
//     over_max          health above max health
//     unattributed      health changed without passing through the watcher
//     unknown_source    a health change from a function not in HPA_SOURCES yet
//     mhp_jump          max health more than doubled within a minute at the same level
//   Every source has to read clean here before stage 2 (server-side death) enforces.
// ═══════════════════════════════════════════════════════════════════════════════
const HPA_LOG = path.join(DATA_DIR, 'hp_audit.log');
const HPA_SUMMARY_MS = Math.max(10000, parseInt(process.env.HPA_SUMMARY_MS, 10) || 10 * 60 * 1000);
const HPA_WINDOW_MS = 60 * 1000;
const HPA_SOURCES = {
  // damage
  sv:'server_hit', _dotTick:'dot', _convTrapsTick:'trap',
  // healing
  hitEnemy:'lifesteal', _upgOnHit:'gear_heal', applySetBonuses:'set_bonus', killBoss:'boss_kill',
  checkLevelUp:'level_up', loop:'regen', tickPassiveRegen:'regen', tickPotionBuffs:'potion',
  useItem:'potion', doDefaultSkill:'potion', updateAutomaton:'pet', tickEarthsense:'racial',
  renderAscPanel:'ascension', _mpOnData:'party',
  // resets and clamps (load, respawn, revive, max-health changes)
  loadGame:'reset', _startGameActual:'reset', returnToLobby:'reset', deathReturn:'reset',
  playerDie:'reset', _mpDeathRespawn:'reset', _soloDeathRespawn:'reset', _pvpHandleDeath:'reset',
  _coopEnterDowned:'reset', _coopDownTick:'reset', _coopOnRevived:'reset',
  applyPassives:'clamp', applyStatBonuses:'clamp',
  // never legitimate online
  tickEditorGodMode:'editor',
  _nonnumeric:'not_a_number',   // a606 — health set to NaN or Infinity (a game bug, flagged)
};
function _hpaLog(o, loud){
  try {
    o.at = new Date().toISOString();
    fs.appendFile(HPA_LOG, JSON.stringify(o) + '\n', () => {});
    fs.stat(HPA_LOG, (e, st) => { if (!e && st.size > 5 * 1024 * 1024) fs.rename(HPA_LOG, HPA_LOG + '.1', () => {}); });
    if (loud) console.warn('[hp-audit] ' + o.t + ' ' + (o.key || '') + ' ' +
      JSON.stringify(Object.assign({}, o, { t:undefined, key:undefined, at:undefined })));
  } catch(e){}
}
function _hpaRec(player){
  if (!player.hpa) player.hpa = {
    key:null, hp:null, mhp:0, lvl:1, def:0, mit:null, zone:null, trial:false, last:0,
    // rolling one-minute window of server hits: sent by the server, landed on the client
    win:{ t0:Date.now(), sent:0, sentN:0, recv:0, recvN:0, landed:0, landedN:0, expect:0, trialMs:0 },
    mhpAt:{ t:Date.now(), mhp:0, lvl:0 },
    sum:{ src:{}, sent:0, sentN:0, landed:0, landedN:0, expect:0, flags:{} },
    flagAt:{}, unknown:{}, touched:false,
  };
  return player.hpa;
}
// one flag per kind per character per minute, so a stuck client can't flood the log
function _hpaFlag(R, t, o){
  const now = Date.now();
  R.sum.flags[t] = (R.sum.flags[t] || 0) + 1;
  if (R.flagAt[t] && now - R.flagAt[t] < 60000) return;
  R.flagAt[t] = now;
  _hpaLog(Object.assign({ t, key:R.key }, o), true);
}
// called from send() for every sv_enemy_attack the server delivers
function _hpaOnSent(ws, data){
  const p = players.get(ws);
  if (!p) return;
  const R = _hpaRec(p);
  const ex = (typeof R.mit === 'number') ? data.dmg * R.mit : 0;
  R.win.sent += data.dmg; R.win.sentN++; R.win.expect += ex;
  R.sum.sent += data.dmg; R.sum.sentN++; R.sum.expect += ex;
}
function _hpaCloseWindow(R, p){
  const W = R.win, now = Date.now();
  if (now - W.t0 < HPA_WINDOW_MS) return;
  // the server meant it: eight or more hits worth half your health after defence,
  // you weren't in a trial, downed or dead, and not one point of it landed
  if (W.sentN >= 8 && R.mhp > 0 && W.expect >= R.mhp * 0.5 && W.landed === 0 &&
      W.trialMs === 0 && !p.downed && !p.dead) {
    _hpaFlag(R, 'no_damage_landed', { hits:W.sentN, raw:Math.round(W.sent), expected:Math.round(W.expect),
                                     received:W.recvN, mhp:R.mhp, lvl:R.lvl, zone:R.zone });
  }
  R.win = { t0:now, sent:0, sentN:0, recv:0, recvN:0, landed:0, landedN:0, expect:0, trialMs:0 };
}
function _hpaOnReport(ws, player, data){
  const key = getSaveKey(String(data.n || player.name || '').slice(0, 20), String(data.r || '').slice(0, 16), String(data.c || '').slice(0, 16));
  if (!key) return;
  const R = _hpaRec(player);
  const now = Date.now();
  if (R.key !== key) { R.key = key; R.hp = null; R.unknown = {}; R.q = null; }   // a different character on this connection
  // a606 — reports are numbered. A missing one (dropped or lost) means its changes are
  //   unknown, so re-anchor on the health reported now instead of flagging a mismatch.
  const q = data.q | 0;
  if (q && R.q !== null && R.q !== undefined && q !== R.q + 1) { R.sum.gaps = (R.sum.gaps || 0) + 1; R.hp = null; }
  if (q) R.q = q;
  R.touched = true;
  const hp = +data.hp, mhp = +data.mhp;
  if (isFinite(mhp) && mhp > 0) R.mhp = Math.round(mhp);
  const _lv = parseInt(data.lvl, 10); if (isFinite(_lv) && _lv >= 1 && _lv <= 200) R.lvl = _lv;
  const _df = +data.def; if (isFinite(_df) && _df >= 0) R.def = Math.round(_df);
  const _mt = +data.mit; R.mit = (data.mit !== null && isFinite(_mt) && _mt > 0 && _mt <= 4) ? _mt : null;
  R.zone = typeof data.zone === 'string' ? data.zone.slice(0, 40) : R.zone;
  const inTrial = !!data.tr;
  if (inTrial) R.win.trialMs += R.last ? (now - R.last) : 2000;
  R.trial = inTrial;
  R.last = now;
  // the changes, by source
  let sum = 0;
  (Array.isArray(data.ev) ? data.ev : []).slice(0, 100).forEach(e => {
    if (!Array.isArray(e)) return;
    const s = String(e[0]).slice(0, 60), d = Math.round(+e[1] || 0), n = e[2] | 0;
    const cat = HPA_SOURCES[s] || ((d < 0 ? 'other_dmg:' : 'other_heal:') + s);
    const S = R.sum.src[cat] || (R.sum.src[cat] = { sum:0, n:0 });
    S.sum += d; S.n += n;
    if (cat === 'editor' && d > 0) _hpaFlag(R, 'editor_heal', { d, zone:R.zone });
    if (s === '_nonnumeric') _hpaFlag(R, 'hp_not_a_number', { n, zone:R.zone });   // a606 — health became NaN/Infinity
    if (!HPA_SOURCES[s] && !R.unknown[s]) { R.unknown[s] = 1; _hpaLog({ t:'unknown_source', key, src:s, d, n }); }
    sum += d;
  });
  // the server's hits as the client saw them
  if (Array.isArray(data.sv)) {
    R.win.recv += +data.sv[0] || 0; R.win.recvN += data.sv[1] | 0;
    R.win.landed += +data.sv[2] || 0; R.win.landedN += data.sv[3] | 0;
    R.sum.landed += +data.sv[2] || 0; R.sum.landedN += data.sv[3] | 0;
  }
  // running copy: last health + reported changes should equal the health reported now
  if (isFinite(hp)) {
    if (R.hp !== null && Math.abs((R.hp + sum) - hp) > 1)
      _hpaFlag(R, 'unattributed', { expected:R.hp + sum, client:hp, d:hp - (R.hp + sum) });
    R.hp = hp;
    if (R.mhp > 0 && hp > R.mhp + 1) _hpaFlag(R, 'over_max', { hp, mhp:R.mhp });
    player.hp = hp; player.maxHp = R.mhp;   // the a578 liveness fields stay in step
  }
  // max health more than doubling inside a minute without a level-up
  if (now - R.mhpAt.t > HPA_WINDOW_MS || R.lvl !== R.mhpAt.lvl) R.mhpAt = { t:now, mhp:R.mhp, lvl:R.lvl };
  else if (R.mhpAt.mhp > 0 && R.mhp > R.mhpAt.mhp * 2) {
    _hpaFlag(R, 'mhp_jump', { from:R.mhpAt.mhp, to:R.mhp, lvl:R.lvl });
    R.mhpAt = { t:now, mhp:R.mhp, lvl:R.lvl };
  }
  _hpaCloseWindow(R, player);
}
// a short, readable summary per active character, to the log and to the console
function _hpaSummary(R, ws){
  const S = R.sum;
  // a606 — messages the server dropped for this connection since the last summary
  const drops = (ws && ws._rlDrops) || null;
  if (ws) ws._rlDrops = null;
  const pct = S.expect > 0 ? Math.round(100 * S.landed / S.expect) : null;
  _hpaLog({ t:'summary', key:R.key, lvl:R.lvl, mhp:R.mhp, def:R.def, mit:R.mit,
            serverHits:S.sentN, serverRaw:Math.round(S.sent), expected:Math.round(S.expect),
            landed:Math.round(S.landed), landedHits:S.landedN, landedPct:pct, src:S.src, flags:S.flags,
            gaps:S.gaps || 0, dropped:drops });
  const fl = Object.keys(S.flags);
  console.log(`[hp-audit] ${R.key} L${R.lvl} mhp ${R.mhp}: server hits ${S.sentN}, landed ${Math.round(S.landed)}` +
              (pct !== null ? ` of ${Math.round(S.expect)} expected (${pct}%)` : '') +
              (fl.length ? ' FLAGS ' + fl.map(f => f + 'x' + S.flags[f]).join(' ') : ', clean') +
              (S.gaps ? `, missing reports ${S.gaps}` : '') +
              (drops ? ', DROPPED ' + Object.keys(drops).map(k => k + ' ' + drops[k]).join(', ') : ''));
  R.sum = { src:{}, sent:0, sentN:0, landed:0, landedN:0, expect:0, flags:{}, gaps:0 };
  R.touched = false;
}
setInterval(() => {
  players.forEach((p, ws) => {
    const R = p.hpa;
    if (!R || !R.key) return;
    _hpaCloseWindow(R, p);
    if (R.touched || R.sum.sentN) _hpaSummary(R, ws);
  });
}, HPA_SUMMARY_MS);

// a580 — another live connection of the same character still in this game?
function _sameCharStillHere(g, leaverWs, name){
  let here = false;
  players.forEach((p, w) => { if (w !== leaverWs && p.gameId === g.id && p.name === name && w.readyState === 1) here = true; });
  return here;
}
// a580 — when the last player drops, PAUSE the game for a grace period instead of deleting
//   it, so a solo player whose connection blips comes back to the same world. An empty
//   game doesn't tick (the loop skips games with no players), so the world simply waits.
const TUN_GRACE_MS = 90 * 1000;
function _tunEndOrPause(gid, g){
  if (g.players.length > 0) return;
  g._pausedAt = Date.now();
  setTimeout(() => { const cur = games.get(gid); if (cur && cur._pausedAt && cur.players.length === 0) games.delete(gid); }, TUN_GRACE_MS + 1000);
}

// a player has left a tunnel game: hand off the host if needed, tell everyone else
function _tunPlayerLeft(g, leaver){
  const rest = _gamePlayers(g).filter(x => x.pid !== leaver.pid);
  if (!rest.length) return false;               // nobody left: caller deletes the game
  if (g.hostPid === leaver.pid) {
    const nh = rest[0];
    g.hostPid = nh.pid; g.host = nh.name;
    const roster = rest.map(x => ({ pid:x.pid, name:x.name }));
    rest.forEach(x => send(x.ws, { type:'sv_tun_host', hostPid:nh.pid, hostName:nh.name, oldPid:leaver.pid,
                                    oldName:leaver.name, me:x.pid, players:roster }));
    broadcast({ type:'lobby_chat', name:'SERVER', msg:g.name + ' is now hosted by ' + nh.name + '.', system:true });
    console.log('[tun] host of game ' + g.id + ' moved ' + leaver.name + ' -> ' + nh.name);
  } else {
    rest.forEach(x => send(x.ws, { type:'sv_tun_left', pid:leaver.pid, name:leaver.name }));
  }
  return true;
}

function removePlayer(ws){
  const player = players.get(ws);
  if(!player) return;
  if(player.gameId){
    const g = games.get(player.gameId);
    if(g){
      // a580 — a tunnel game survives its host: hand it on rather than delete it
      if (g.tun) {
        if (!player._retired) _tunPlayerLeft(g, player);   // a retired (stale) socket was already handed over
        else { const rest = _gamePlayers(g).filter(x => x.pid !== player.pid);
               rest.forEach(x => send(x.ws, { type:'sv_tun_left', pid:player.pid, name:player.name })); }
        if (!_sameCharStillHere(g, ws, player.name)) g.players = g.players.filter(n => n !== player.name);
        _tunEndOrPause(player.gameId, g);
        broadcastGameList();
        player.gameId = null;
        if (player.name) broadcast({ type:'lobby_chat', name:'SERVER', msg:player.name+' left the lobby.', system:true });
        wsByPid.delete(player.pid);
        players.delete(ws);
        broadcast({ type:'player_count', count:players.size });
        broadcastPlayerList();
        return;
      }
      g.players = g.players.filter(n => n !== player.name);
      // If the host disconnected, delete the game entirely
      if(g.host === player.name){
        games.delete(player.gameId);
        broadcast({ type:'lobby_chat', name:'SERVER',
          msg:g.name+' ended (host disconnected).', system:true });
      } else if(g.players.length === 0){
        // Last player left — clean it up
        games.delete(player.gameId);
      }
      broadcastGameList();
    }
    player.gameId = null;
  }
  if(player.name){
    broadcast({ type:'lobby_chat', name:'SERVER', msg:player.name+' left the lobby.', system:true });
  }
  wsByPid.delete(player.pid);   // a580
  players.delete(ws);
  broadcast({ type:'player_count', count:players.size });
  broadcastPlayerList();
}

// ══════════════════════════════════════════════════════════
// WEBSOCKET
// ══════════════════════════════════════════════════════════

// a606 — per-kind message allowances (messages per second, and burst)
const _RL_LIMITS = {
  fx:    { rate:40, burst:60 },    // spell effects (client already caps these at 30/s)
  hit:   { rate:80, burst:160 },   // hits on mobs and bosses: an AoE sends one per target
  core:  { rate:15, burst:30 },    // position, health and gold reports
  other: { rate:30, burst:60 },    // everything else, as before
};
const _RL_KIND = {
  sv_vfx:'fx',
  sv_hit_enemy:'hit', sv_hit_boss:'hit', sv_worldboss_hit:'hit',
  sv_player_state:'core', sv_hpa:'core', sv_econ:'core',
};
setInterval(()=>{
  wss.clients.forEach(ws=>{
    if(ws.isAlive === false){ removePlayer(ws); return ws.terminate(); }
    ws.isAlive = false; ws.ping();
  });
}, 20000);

// ═══════════════════════════════════════════════════════════════════════════════
// a721 — GROUND DROPS. A player can drag anything out of their bag onto the ground;
//   it lands a few steps in front of them and anyone in the zone can walk over it to
//   pick it up. The server owns every dropped item so exactly one player gets it: the
//   first pickup request wins, everyone else is told it's gone. The whole bag entry
//   travels (affixes, sockets, gems, upgrades, stack size). Items stay 5 minutes.
//   Party games share the ground per zone; a player not in a party gets a private one.
// ═══════════════════════════════════════════════════════════════════════════════
const _GD = new Map();           // 'scope|zone' -> Map(gid -> drop)
const _GD_LIFE = 5 * 60 * 1000, _GD_CAP = 150;
let _gdSeq = 0;
function _gdScope(p){ return p.gameId ? 'g:' + p.gameId : 's:' + p.pid; }
function _gdZoneOk(z){ return typeof z === 'string' && z.length > 0 && z.length <= 40; }
function _gdBucket(scope, zone, make){
  const k = scope + '|' + zone; let b = _GD.get(k);
  if (!b && make) { b = new Map(); _GD.set(k, b); }
  return b;
}
function _gdSend(scope, zone, msg){
  const s = JSON.stringify(msg);
  players.forEach((p, w) => { if (w.readyState === 1 && p.zone === zone && _gdScope(p) === scope) w.send(s); });
}
function _gdClean(e){
  if (!e || typeof e !== 'object') return null;
  let s; try { s = JSON.stringify(e); } catch (x) { return null; }
  if (s.length > 4000) return null;
  const c = JSON.parse(s);
  if (typeof c.id !== 'string' || !c.id || c.id.length > 64) return null;
  c.qty = Math.max(1, Math.min(99999, parseInt(c.qty, 10) || 1));
  return c;
}
function _gdPub(d){ return { gid:d.gid, zone:d.zone, x:d.x, z:d.z, e:d.e, by:d.by, t:d.t }; }
function _gdSnapshot(ws, p, zone){
  const b = _gdBucket(_gdScope(p), zone, false);
  const list = b ? [...b.values()].map(_gdPub) : [];
  send(ws, { type:'sv_gsnap', zone, list });
}
setInterval(() => {
  const now = Date.now();
  _GD.forEach((b, k) => {
    const scope = k.slice(0, k.indexOf('|'));
    b.forEach((d, gid) => {
      if (now - d.t > _GD_LIFE) { b.delete(gid); _gdSend(scope, d.zone, { type:'sv_ggone', gid, zone:d.zone }); }
    });
    if (!b.size) _GD.delete(k);
  });
}, 10000);

wss.on('connection', ws => {
  ws.isAlive = true;
  ws.on('pong', ()=>{ ws.isAlive = true; });
  players.set(ws, { name:'', gameId:null, zone:null, x:undefined, z:undefined, pid: ++_pidSeq });   // a578 — pid
  wsByPid.set(players.get(ws).pid, ws);   // a580

  ws.on('message', raw => {
    ws.isAlive = true;
    // a481 — SERVER-2: per-connection rate limit. Token bucket, ~30 msg/sec with a
    //   burst allowance of 60. Prevents a single client from flooding the handler
    //   (and, via sv_cloud_save, hammering disk writes). Legitimate play sends a
    //   handful of messages per second; state updates are the most frequent and sit
    //   well under this. Over-budget messages are silently dropped.
    // a580 — byte budget (3MB burst, 300KB/s), so the larger frame cap can't be abused
    {
      const _nb = Date.now(), _len = (raw && raw.length) || 0;
      if (ws._bbTokens === undefined) { ws._bbTokens = 3 * 1024 * 1024; ws._bbLast = _nb; }
      ws._bbTokens = Math.min(3 * 1024 * 1024, ws._bbTokens + (_nb - ws._bbLast) * 300);
      ws._bbLast = _nb;
      if (_len > ws._bbTokens) return;
      ws._bbTokens -= _len;
    }
    // a580 — presence tunnel frames have their own budget (see TUNNEL below)
    if ((typeof raw === 'string' ? raw.slice(0, _TUN_HEAD.length) : raw.slice(0, _TUN_HEAD.length).toString()) === _TUN_HEAD) {
      _tunOnFrame(ws, raw);
      return;
    }
    let data;
    try { data = JSON.parse(raw); } catch { return; }
    // a606 — one allowance PER KIND of message instead of one shared 30/s bucket. The
    //   client may send up to 30 spell-effect messages a second on its own, which used the
    //   whole shared allowance: in a busy fight the server then silently dropped your hits
    //   on mobs (measured: 19 of 40 lost), your health reports and anything else. Effects,
    //   hits and position/health reports now each have their own allowance, so cosmetic
    //   traffic can never starve gameplay. Everything else keeps the old 30/s.
    if (!data || typeof data !== 'object') return;
    {
      const _k = _RL_KIND[data.type] || 'other', L = _RL_LIMITS[_k], _now = Date.now();
      const B = ws._rl || (ws._rl = {});
      const b = B[_k] || (B[_k] = { t:L.burst, at:_now });
      b.t = Math.min(L.burst, b.t + (_now - b.at) * (L.rate / 1000));
      b.at = _now;
      if (b.t < 1) {   // over budget — drop, and count it so the HP audit summary can show it
        const D = ws._rlDrops || (ws._rlDrops = {});
        const _ty = String(data.type).slice(0, 30);
        D[_ty] = (D[_ty] || 0) + 1;
        return;
      }
      b.t -= 1;
    }
    const player = players.get(ws);

    switch(data.type){

      // ── LOBBY ──────────────────────────────────────────
      case 'login':
        player.name = (data.name||'').slice(0,20).replace(/[<>]/g,'') || 'Adventurer';
        // v93.0-a66 — capture level/class/race for the player list display.
        // Sanitize: clamp level, strip dangerous chars from strings, length-limit.
        {
          const _lv = parseInt(data.level, 10);
          player.level = (isFinite(_lv) && _lv >= 1 && _lv <= 200) ? _lv : 1;
          player.cls = (typeof data.cls === 'string' ? data.cls : 'Warrior')
                        .slice(0,16).replace(/[<>&"']/g,'') || 'Warrior';
          player.raceId = (typeof data.raceId === 'string' ? data.raceId : 'xu')
                          .slice(0,16).replace(/[^a-z_]/g,'') || 'xu';
          player.raceName = (typeof data.raceName === 'string' ? data.raceName : 'Xu')
                            .slice(0,16).replace(/[<>&"']/g,'') || 'Xu';
          // v93.0-a256 — ascendancy level for the player list. Clamp to a sane range.
          const _asc = parseInt(data.asc, 10);
          player.asc = (isFinite(_asc) && _asc >= 0 && _asc <= 99999) ? _asc : 0;
          // a596 — character portrait for the lobby list
          { const _pt = _cleanPortrait(data.portrait); if (_pt) { player.portrait = _pt; player.pv = ++_portraitSeq; } }
          // v93.0-a258 — guild tag is resolved server-side from our persisted guild
          // registry (see getPlayerSummary → _serverGuildTag). We intentionally do NOT
          // trust data.guildTag: the client's myGuild isn't populated until the server
          // sends guild_info (later in this handler), so at login it was always null.
        }
        send(ws, { type:'logged_in', name:player.name, tun:1, pid:player.pid });   // a580 — tunnel available
        sendGameList(ws);
        send(ws, { type:'player_count', count:players.size });
        send(ws, { type:'player_list', players:getPlayerSummary() });
        broadcast({ type:'lobby_chat', name:'SERVER', msg:player.name+' entered the lobby.', system:true }, ws);
        broadcast({ type:'player_count', count:players.size });
        broadcastPlayerList();
        // Send guild info (if any)
        {
          const _g = findPlayerGuild(player.name);
          send(ws, {type:'guild_info', guildId:_g?_g.id:null, guild:_g?_g.guild:null});
        }
        break;

      case 'set_portrait': {   // a596 — gear changed: new face for the lobby list
        if (!player.name) break;
        const _pt = _cleanPortrait(data.portrait);
        if (!_pt || _pt === player.portrait) break;
        const _now = Date.now();
        if (player._portraitAt && _now - player._portraitAt < 5000) break;
        player._portraitAt = _now;
        player.portrait = _pt; player.pv = ++_portraitSeq;
        broadcastPlayerList();
        break;
      }
      case 'get_portraits': {   // a596 — images for the names a client is missing
        if (!Array.isArray(data.names)) break;
        const items = {};
        const want = new Set(data.names.slice(0, 40).map(String));
        for (const p of players.values()) {
          if (p.name && p.portrait && want.has(p.name)) items[p.name] = { pv: p.pv || 0, img: p.portrait };
        }
        send(ws, { type:'portraits', items });
        break;
      }
      case 'lobby_chat':
        if(!player.name) break;
        const msg = (data.msg||'').slice(0,200).replace(/[<>]/g,'');
        if(!msg) break;
        broadcast({ type:'lobby_chat', name:player.name, msg });
        break;

      case 'request_player_list':
        send(ws, { type:'player_list', players:getPlayerSummary() });
        break;

      // ── CLOUD SAVES ────────────────────────────────────
      case 'sv_cloud_save': {
        // Client is uploading a save — store it
        if (!data.name || !data.raceId || !data.cls || !data.saveData) break;
        const name = data.name.slice(0,20).replace(/[^a-zA-Z0-9_\- ]/g,'');
        if (!name) break;
        const key = getSaveKey(name, data.raceId, data.cls);
        const incoming = data.saveData;
        // a481 — SERVER-2: per-save size cap. maxPayload already bounds the frame,
        //   but cap the stored blob too so no single save can bloat the file.
        // a580 — the cap was 200KB, which a big inventory reaches at roughly 2,200 items;
        //   past it, saves were silently skipped and the character stopped being backed up.
        if (JSON.stringify(incoming).length > SAVE_MAX_BYTES) {
          send(ws, { type:'sv_cloud_save_ok', key, skipped:true, error:'save_too_large' });
          break;
        }
        // a481 — SERVER-1: ownership. The client sends a locally-generated token.
        //   If this key has no owner yet (new save, or a legacy pre-token save), the
        //   presenting token CLAIMS it. If it's already owned, the token must match
        //   or we refuse — this is what stops someone overwriting/griefing a save
        //   they don't own just by knowing the character name.
        const token = _validToken(data.token) ? data.token : null;
        const owner = saveOwners[key];
        if (owner) {
          if (!token || token !== owner) {
            send(ws, { type:'sv_cloud_save_denied', key, reason:'not_owner' });
            console.log(`[saves] DENIED overwrite of owned key ${key} (token mismatch)`);
            break;
          }
        } else if (token) {
          saveOwners[key] = token;   // claim
          console.log(`[saves] Key ${key} claimed by presenting token.`);
        }
        const existing = cloudSaves[key];
        // Only overwrite if incoming is newer
        if (!existing || (incoming.ts && incoming.ts > (existing.ts||0))) {
          const _wipe = _saveLooksLikeWipe(existing, incoming);
          if (_wipe) {
            savesPrev[key] = { data: existing, ts: Date.now(), reason: _wipe };
            console.warn('[saves] Kept the previous version of ' + key + ' (' + _wipe + ')');
          }
          try { _econOnSave(key, incoming); } catch(e){}   // a582 — compare against the running gold copy
          cloudSaves[key] = incoming;
          flushSaves();
          send(ws, { type:'sv_cloud_save_ok', key, ts: incoming.ts });
          console.log(`[saves] Saved: ${key} (ts=${incoming.ts})`);
        } else {
          send(ws, { type:'sv_cloud_save_ok', key, ts: existing.ts, skipped:true });
        }
        break;
      }

      case 'sv_cloud_load': {
        // Client requesting all saves for a username
        if (!data.name) break;
        const name = data.name.slice(0,20).replace(/[^a-zA-Z0-9_\- ]/g,'');
        if (!name) break;
        // a481 — SERVER-1: ownership-gated load. A save is returned only when the
        //   requester presents its owner token, OR the save is still un-owned (in
        //   which case presenting a valid token claims it — this is how a returning
        //   legacy player, or the same player on a new device with their stored
        //   token, recovers their character). Un-owned + no token still returns the
        //   save (so first-ever load before the client has minted a token works),
        //   but that window closes permanently the moment an owner is recorded.
        const token = _validToken(data.token) ? data.token : null;
        const all = getAllSavesForUser(name);
        const saves = [];
        for (const rec of all) {
          const owner = saveOwners[rec.key];
          if (owner) {
            if (token && token === owner) saves.push(rec);   // owner — allowed
            // else: owned by someone else — silently omit (no theft)
          } else {
            if (token) saveOwners[rec.key] = token;          // claim on load
            saves.push(rec);
          }
        }
        if (Object.keys(saveOwners).length) flushSaves(); // persist any claims
        send(ws, { type:'sv_cloud_load_result', saves, name });
        console.log(`[saves] Load request for '${name}': ${saves.length}/${all.length} save(s) returned (ownership-filtered)`);
        break;
      }

      case 'sv_cloud_load_one': {
        // Client requesting a single specific save key
        if (!data.key) break;
        // a481 — SERVER-1: same ownership gate as bulk load.
        const token = _validToken(data.token) ? data.token : null;
        const owner = saveOwners[data.key];
        if (owner && (!token || token !== owner)) {
          send(ws, { type:'sv_cloud_load_one_result', key: data.key, save: null, denied:true });
          break;
        }
        if (!owner && token && cloudSaves[data.key]) { saveOwners[data.key] = token; flushSaves(); }
        const save = cloudSaves[data.key] || null;
        send(ws, { type:'sv_cloud_load_one_result', key: data.key, save });
        break;
      }

      case 'create_game': {
        if(player.gameId){
          const old = games.get(player.gameId);
          if(old && old.host===player.name) games.delete(player.gameId);
          player.gameId = null;
        }
        const gId = nextGameId++;
        const game = {
          id:gId, name:(data.name||player.name+"'s Game").slice(0,40),
          host:player.name, hostPeer:data.hostPeer,
          tun: data.hostPeer === 'tun', hostPid: player.pid,   // a580
          zone:data.zone||'XU Outpost', password:data.password||'',
          maxPlayers:Math.min(data.max||4,4), players:[player.name],
          createdAt:Date.now(),
          started: false,
          zones: {}, // pre-populated below
        };
        // Pre-initialize ALL zones immediately so enemies exist before anyone enters
        // This is the MMO-style approach: server owns all zones always
        Object.keys(ZONE_SPAWNS).forEach(zoneName => {
          game.zones[zoneName] = {
            enemies: createZoneEnemies(zoneName),
            lastActivity: Date.now(),
            boss: ZONE_BOSS_HP[zoneName] ? {
              hp: ZONE_BOSS_HP[zoneName].hp,
              maxHp: ZONE_BOSS_HP[zoneName].hp,
              phase: 1,
              spawned: false,
              name: ZONE_BOSS_HP[zoneName].name,
            } : null,
          };
        });
        _convInitZone(game.zones.convergence, 'convergence');   // a599
        games.set(gId, game);
        player.gameId = gId;
        send(ws, { type:'game_created', game, pid:player.pid });
        broadcastGameList();
        break;
      }

      case 'update_game':
        if(player.gameId){
          const ug = games.get(player.gameId);
          if(ug && ug.host===player.name){
            if(data.zone) ug.zone = data.zone.slice(0,40);
            broadcastGameList();
          }
        }
        break;

      case 'join_game': {
        const jGame = games.get(data.id);
        if(!jGame){ send(ws,{type:'join_error',msg:'Game not found.'}); break; }
        if(jGame.players.length>=jGame.maxPlayers){ send(ws,{type:'join_error',msg:'Game is full.'}); break; }
        if(jGame.password&&jGame.password!==data.password){ send(ws,{type:'join_error',msg:'Wrong password.'}); break; }
        if(!jGame.players.includes(player.name)) jGame.players.push(player.name);
        player.gameId = data.id;
        if (jGame.tun) {
          // a580 — introduce the joiner to the host through the tunnel, then let them in
          const _hw = wsByPid.get(jGame.hostPid);
          if (_hw) send(_hw, { type:'sv_tun_conn', from:player.pid, name:player.name });
          send(ws, { type:'join_success', tun:1, hostPid:jGame.hostPid, pid:player.pid, game:jGame });
          broadcastGameList();
          break;
        }
        send(ws, { type:'join_success', hostPeer:jGame.hostPeer, game:jGame });
        broadcastGameList();
        break;
      }

      case 'leave_game':
        if(player.gameId){
          const lg = games.get(player.gameId);
          if(lg && lg.tun){
            // a580 — leaving a tunnel game hands it on instead of ending it. A deliberate
            //   leave ends an empty game straight away; only a dropped connection is paused.
            _tunPlayerLeft(lg, player);
            if (!_sameCharStillHere(lg, ws, player.name)) lg.players = lg.players.filter(n => n !== player.name);
            if (lg.players.length === 0) games.delete(player.gameId);
            broadcastGameList();
          } else if(lg){
            lg.players = lg.players.filter(n => n !== player.name);
            if(data.isHost===true && lg.host===player.name){
              games.delete(player.gameId);
              broadcast({type:'lobby_chat',name:'SERVER',msg:lg.name+' ended.',system:true});
            }
            broadcastGameList();
          }
          player.gameId = null;
          player.zone   = null;
        }
        break;

      case 'request_game_list':
        sendGameList(ws);
        break;

      // ── IN-GAME: player position & zone ───────────────
      case 'sv_player_state':
        // a752 — a late packet from the zone you just left must not drag you back into it
        if (player._arriving && data.zone !== player.zone) break;
        if (player._arriving) { player._arriving = false; player._graceUntil = Date.now() + 1500; }
        // Client sends position + current zone each tick
        player.x    = data.x;
        player.z    = data.z;
        player.zone = data.zone;
        // a578 — health and downed ride on the state packet: no extra traffic, and a
        //   dropped downed/alive event heals itself within a fraction of a second
        if (typeof data.hp === 'number')  player.hp    = data.hp;
        if (typeof data.mhp === 'number') player.maxHp = data.mhp;
        if (data.dn !== undefined)        player.downed = !!data.dn;
        if (player.gameId) {
          const g = games.get(player.gameId);
          if (g) g.started = true;
        }
        break;

      // ── a582 — gold audit report (shadow mode) ──
      case 'sv_econ':
        try { _econOnReport(data); } catch(e){ console.warn('[econ] report error', e.message); }
        break;

      // ── a605 — HP audit report (shadow mode) ──
      case 'sv_hpa':
        try { _hpaOnReport(ws, player, data); } catch(e){ console.warn('[hp-audit] report error', e.message); }
        break;

      // ── a580 — rejoin a tunnel game after the connection dropped ──
      case 'sv_tun_rejoin': {
        const g = games.get(data.gameId | 0);
        if (!g || !g.tun || !player.name) { send(ws, { type:'sv_tun_rejoin_fail' }); break; }
        if (!g.players.includes(player.name)) {
          if (g.players.length >= g.maxPlayers) { send(ws, { type:'sv_tun_rejoin_fail' }); break; }
          g.players.push(player.name);
        }
        g._pausedAt = null;
        player.gameId = g.id;
        // this character's older, stale connections in the same game
        const stale = [];
        players.forEach((p, w) => { if (w !== ws && p.gameId === g.id && p.name === player.name) stale.push([w, p]); });
        const hostWs = wsByPid.get(g.hostPid);
        const wasHost = stale.some(([w, p]) => p.pid === g.hostPid) || (g.host === player.name && (!hostWs || hostWs.readyState !== 1));
        if (wasHost) {
          // you were hosting: you get it back, on your new connection
          const oldPid = g.hostPid;
          g.hostPid = player.pid; g.host = player.name;
          const live = _gamePlayers(g).filter(x => !stale.some(([w]) => w === x.ws));
          const roster = live.map(x => ({ pid:x.pid, name:x.name }));
          live.forEach(x => send(x.ws, { type:'sv_tun_host', hostPid:player.pid, hostName:player.name, oldPid,
                                          oldName:player.name, me:x.pid, players:roster, rejoin:1 }));
        } else {
          if (hostWs && hostWs.readyState === 1) send(hostWs, { type:'sv_tun_conn', from:player.pid, name:player.name });
          send(ws, { type:'sv_tun_rejoined', hostPid:g.hostPid, pid:player.pid, game:g });
        }
        // retire the stale sockets now — they're no longer the host, so their departure is ordinary
        stale.forEach(([w, p]) => { p._retired = true; try { w.terminate(); } catch(e){} });
        broadcastGameList();
        break;
      }

      // ── a578 — liveness events ──
      case 'sv_player_downed':
        player.downed = true; player.dead = false; player.hp = 0;
        player._downedAt = Date.now();
        if (player.gameId && player.zone)
          broadcastToZone(player.gameId, player.zone, { type:'sv_party_event', ev:'downed', id:player.pid, n:player.name }, ws);
        break;
      case 'sv_player_dead':
        player.downed = false; player.dead = true; player.hp = 0;
        if (player.gameId && player.zone)
          broadcastToZone(player.gameId, player.zone, { type:'sv_party_event', ev:'dead', id:player.pid, n:player.name }, ws);
        break;
      case 'sv_player_alive':
        player.downed = false; player.dead = false;
        if (typeof data.hp === 'number') player.hp = data.hp;
        if (typeof data.mhp === 'number') player.maxHp = data.mhp;
        if (player.gameId && player.zone)
          broadcastToZone(player.gameId, player.zone, { type:'sv_party_event', ev:'alive', id:player.pid, n:player.name }, ws);
        break;

      // ── a578 — REVIVE, validated server-side ──
      //   Two messages so the 3s hold is enforced here, not trusted from the client:
      //   start records who you're reviving and when; finish is only honoured if it
      //   comes at least REVIVE_HOLD_MS later, and both are checked against the server's
      //   own positions — the reviver standing, the target downed, same zone, in range.
      case 'sv_revive_start':
      case 'sv_revive': {
        if (!player.gameId || !player.zone || !isTargetable(player)) { player._revT = null; break; }
        const _tid = data.target | 0;
        let _tws = null, _tp = null;
        players.forEach((p, w) => {
          if (p.gameId === player.gameId && p.zone === player.zone && p.pid === _tid) { _tws = w; _tp = p; }
        });
        if (!_tp || _tp === player || !_tp.downed || _tp.dead ||
            _tp.x === undefined || player.x === undefined) { player._revT = null; break; }
        const _dx = _tp.x - player.x, _dz = _tp.z - player.z;
        if (_dx*_dx + _dz*_dz > REVIVE_RANGE*REVIVE_RANGE) { player._revT = null; break; }
        if (data.type === 'sv_revive_start') { player._revT = { id:_tid, at:Date.now() }; break; }
        if (!player._revT || player._revT.id !== _tid || Date.now() - player._revT.at < REVIVE_HOLD_MS) break;
        player._revT = null;
        _tp.downed = false; _tp.dead = false;
        try { _tws.send(JSON.stringify({ type:'sv_revived', by:player.name, byId:player.pid })); } catch(e){}
        broadcastToZone(player.gameId, player.zone,
          { type:'sv_party_event', ev:'revived', id:_tp.pid, n:_tp.name, by:player.name });
        break;
      }

      case 'sv_enter_zone': {
        player.zone = data.zone;
        player._arriving = true; player._graceUntil = 0;   // a752 — the x/z we hold are from the zone you just left
        player.downed = false; player.dead = false;   // a578 — arriving somewhere means you're up
        if(!player.name && data.name) player.name = data.name.slice(0,20).replace(/[<>]/g,'');

        // Recover gameId if lost after WS reconnect
        if (!player.gameId && player.name) {
          games.forEach((g, gid) => {
            if (g.players.includes(player.name)) {
              player.gameId = gid;
              console.log(`[sv_enter_zone] Recovered gameId=${gid} for player ${player.name}`);
            }
          });
        }

        console.log(`[sv_enter_zone] player=${player.name} zone=${data.zone} gameId=${player.gameId} games=${games.size}`);

        if (_gdZoneOk(data.zone)) _gdSnapshot(ws, player, data.zone);   // a721 — what's lying on the floor here
        if (!player.gameId) {
          console.log(`[sv_enter_zone] DROPPED — no gameId for ${player.name}`);
          break;
        }
        const g = games.get(player.gameId);
        if (!g) {
          console.log(`[sv_enter_zone] DROPPED — game not found for ${player.name} gameId=${player.gameId}`);
          break;
        }
        const zoneEnemyCount = g.zones[data.zone] ? g.zones[data.zone].enemies.length : 0;
        const activeCount = g.zones[data.zone] ? g.zones[data.zone].enemies.filter(e=>e.active).length : 0;
        console.log(`[sv_enter_zone] Sending snapshot: zone=${data.zone} total=${zoneEnemyCount} active=${activeCount}`);
        g.started = true;
        sendZoneSnapshot(ws, g, data.zone);
        // a233 — CO-OP: hand the entering player the authoritative run seed + depth
        //   + mods for procedural zones so they build the SAME map as everyone else
        //   and join the in-progress depth instead of resetting it.
        if (data.zone === 'convergence' || data.zone === 'the_reach') {
          const _pz = getOrCreateZone(g, data.zone);
          send(ws, buildRunState(_pz, data.zone));
        }
        broadcastToZone(g.id, data.zone, {
          type:'sv_player_entered', name:player.name, zone:data.zone
        }, ws);
        // Global announce to all players in the game
        broadcastToGame(g.id, {
          type:'sv_zone_entered_announce',
          name: player.name,
          zone: data.zone,
        }, ws);
        // Send current boss state to the entering player
        const _entBoss = g.zones[data.zone] && g.zones[data.zone].boss;
        if (_entBoss && _entBoss.spawned && _entBoss.hp > 0) {
          send(ws, {
            type:'sv_boss_state',
            zone: data.zone,
            hp: _entBoss.hp,
            maxHp: _entBoss.maxHp,
            phase: _entBoss.phase,
            bossName: _entBoss.name,
          });
        }
        break;
      }

      case 'sv_hit_enemy': {
        if (!player.gameId || !player.zone) break;
        const g = games.get(player.gameId);
        if (!g) break;
        const zone = g.zones[player.zone];
        if (!zone) break;
        const e = zone.enemies.find(en => en.id === data.id && en.active);
        if (!e) break;

        // Anti-cheat distance check — 24 units for ranged/magic, 10 for melee
        if (player.x !== undefined) {
          const dx = player.x - e.x, dz = player.z - e.z;
          const maxRange = (data.ranged || data.magic) ? 24*24 : 10*10;
          if (dx*dx + dz*dz > maxRange) break;
        }

        // Cap incoming damage to reasonable max (anti-hack)
        const cappedDmg = Math.min(data.dmg||1, 999999);
        const rawDmg = Math.max(1, Math.floor(cappedDmg * (1 - (e.dmgReduction||0))));
        e.hp -= rawDmg;
        // a597 — getting hit always pulls the mob onto its attacker
        e.aggroed = true; e._tgt = player.name; e._tgtAt = Date.now();

        if (e.hp <= 0) {
          e.hp = 0; e.active = false; e.aggroed = false; e.respawnTimer = 0;
          // Broadcast kill to everyone in zone — include killer so only they get loot
          broadcastToZone(g.id, player.zone, {
            type:'sv_enemy_killed',
            id:e.id, etype:e.type, zone:player.zone,
            reward:e.reward, expR:e.expR,
            ex:+e.x.toFixed(2), ez:+e.z.toFixed(2),
            killer: player.name
          });
          // Award guild XP based on enemy expR value
          awardGuildXp(player.name, Math.max(1, Math.floor((e.expR||1) / 2)));
        } else {
          // Broadcast HP update to everyone in zone
          broadcastToZone(g.id, player.zone, {
            type:'sv_enemy_hit',
            id:e.id, hp:e.hp, maxHp:e.maxHp,
            dmg:rawDmg, ex:+e.x.toFixed(2), ez:+e.z.toFixed(2)
          });
        }
        break;
      }

      // a555 — THE FURNACE CORE's WEAK POINT WINDOW. The core periodically exposes and
      //   takes 1.6x damage, but that multiplier lived only in the client's own hitBoss
      //   path — so in multiplayer the core opened, the flare played, and your damage was
      //   completely unchanged. The server resolves boss HP, so it has to own the window.
      //   Same class of defect as the a551 armour lock, inverted: a vulnerability that
      //   never actually made the boss vulnerable.
      case 'sv_hit_boss': {
        if (!player.gameId || !player.zone) break;
        const g = games.get(player.gameId);
        if (!g) break;
        const zone = g.zones[player.zone];
        if (!zone) break;
        // v93.0-a116 -- defensive: auto-init boss if missing instead of silently dropping
        // the hit. Previously a missing zone.boss caused all hits to be dropped with no
        // error, leading to "immortal boss" reports. Now we lazy-create the boss when
        // the first hit arrives, using the depth scaling that should have been applied.
        if (!zone.boss && ZONE_BOSS_HP[player.zone]) {
          console.warn(`[boss] zone.boss missing for ${player.zone} on first hit. Auto-initializing.`);
          const _curDepth = zone.convergenceDepth || 1;
          const _depthMul = player.zone === 'convergence' ? (1.0 + 0.5 * (_curDepth - 1)) : 1.0;
          const _baseHp = ZONE_BOSS_HP[player.zone].hp;
          zone.boss = {
            hp: Math.round(_baseHp * _depthMul),
            maxHp: Math.round(_baseHp * _depthMul),
            phase: 1,
            spawned: true,
            name: ZONE_BOSS_HP[player.zone].name,
          };
        }
        if (!zone.boss) break;
        const b = zone.boss;
        // v93.0-a116 -- if boss exists but isn\'t marked spawned, mark it spawned NOW.
        // This prevents the case where the boss was reset (e.g. on depth transition)
        // but the client already started attacking and the spawned flag was stale.
        if (!b.spawned) {
          // a298 — INSTANT-RESPAWN FIX. Do NOT resurrect a DEAD boss from a stray
          //   hit. A high-DPS player vs a low-HP boss (the Wildmother is 35k) lands
          //   extra hits in the network round-trip window AFTER the kill; those
          //   arrived here with spawned=false + hp<=0, the old a226 code refilled
          //   HP to full and re-broadcast a spawn -> the boss instantly respawned
          //   (free XP farm) and the 5-minute lock was bypassed. A dead boss now
          //   respawns ONLY via the timed sv_boss_respawn below. A live boss with a
          //   merely-stale spawned flag (reconnect / depth-set / 2nd player) still
          //   auto-spawns and KEEPS its current HP (the a226 heal-to-full fix holds).
          if (b.hp <= 0) break;
          console.warn(`[boss] zone.boss.spawned was false in ${player.zone} on hit; auto-spawning.`);
          b.spawned = true;
          broadcastToZone(g.id, player.zone, {
            type: 'sv_boss_spawned',
            zone: player.zone,
            bossName: b.name,
            hp: b.hp,
            maxHp: b.maxHp,
          });
        }
        if (b.hp <= 0) break;

        // Cap damage (anti-cheat)
        // a555 — THE FURNACE CORE's WEAK POINT WINDOW. The core periodically exposes and
        //   takes 1.6x damage, but that multiplier lived only in the client's own hitBoss
        //   path — so in multiplayer the core opened, the flare played, and the damage was
        //   unchanged. The server resolves boss HP, so it has to own the window. Same class
        //   of defect as the a551 armour lock, inverted: a vulnerability that never made
        //   the boss vulnerable.
        let _inDmg = data.dmg || 1;
        if (player.zone === 'forge' && b._fcWeak) _inDmg = Math.floor(_inDmg * 1.6);
        if (player.zone === 'the_reach' && b._keLinkDR) _inDmg = Math.max(1, Math.floor(_inDmg * (1 - b._keLinkDR)));   // a619 — Sentient Link
        const bdmg = Math.min(_inDmg, 999999);
        b.hp = Math.max(0, b.hp - bdmg);

        // Broadcast HP update to all players in zone
        broadcastToZone(g.id, player.zone, {
          type: 'sv_boss_hp',
          zone: player.zone,
          hp: b.hp,
          maxHp: b.maxHp,
          phase: b.phase,
          dmg: bdmg,
          hitter: player.name,
        });

        // Phase transitions — broadcast to zone.
        // a555 — SKIP for any zone with a ZBOSS_SERVER config: tickZoneBoss owns the phase
        //   ladder there, and this generic .75/.50/.25/.10 one was running in ADDITION to it.
        //   The two interleaved (each advancing b.phase past the other's guard), so a
        //   migrated boss could skip a phase or overshoot its own maximum — THE FURNACE CORE
        //   has three phases and this drove it to four. Every boss migrated since a548 was
        //   sharing its ladder with this one; the config is the single source of truth now.
        const pct = b.hp / b.maxHp;
        const oldPhase = b.phase;
        if (!ZBOSS_SERVER[player.zone]) {
          if (b.phase === 1 && pct <= 0.75) b.phase = 2;
          else if (b.phase === 2 && pct <= 0.50) b.phase = 3;
          else if (b.phase === 3 && pct <= 0.25) b.phase = 4;
          else if (b.phase === 4 && pct <= 0.10) b.phase = 5;
        }
        if (b.phase !== oldPhase) {
          broadcastToZone(g.id, player.zone, {
            type: 'sv_boss_phase',
            zone: player.zone,
            phase: b.phase,
            bossName: b.name,
          });
        }

        // Boss killed
        if (b.hp <= 0) {
          b.spawned = false;
          b.hp = 0;
          // Broadcast kill to entire zone
          broadcastToZone(g.id, player.zone, {
            type: 'sv_boss_killed',
            zone: player.zone,
            bossName: b.name,
            killer: player.name,
            bx: data.bx || 0,
            bz: data.bz || 0,
          });
          // Global announce to ENTIRE game — everyone sees the kill
          broadcastToGame(g.id, {
            type: 'sv_world_announce',
            msg: `⚔ ${player.name} SLEW ${b.name} in ${player.zone.replace(/_/g,' ').toUpperCase()}!`,
            zone: player.zone,
            killer: player.name,
            bossName: b.name,
          });
          // Award large guild XP for boss kill — scales with boss HP
          awardGuildXp(player.name, Math.max(100, Math.floor((b.maxHp||1000) / 500)));
          b.killedAt = Date.now();
          // a298 — respawn after 5 minutes (was 3) to match the client's hard
          //   BOSS_RESPAWN_MS lock, so server + client agree on the cooldown.
          // Capture bossZone NOW — player.zone may change before the timer fires
          const bossZone = player.zone;
          setTimeout(() => {
            if (g && g.zones[bossZone] && g.zones[bossZone].boss) {
              const rb = g.zones[bossZone].boss;
              rb.hp = rb.maxHp;
              rb.phase = 1;
              rb.spawned = false; // will re-spawn when triggered client-side
              rb.killedAt = 0;    // a298 — clear the death stamp; cooldown is over
              broadcastToZone(g.id, bossZone, {
                type: 'sv_boss_respawn', zone: bossZone, bossName: rb.name,
              });
            }
          }, 5 * 60 * 1000);
        }
        break;
      }

      // ──────────────────────────────────────────────────────
      // a146 — WORLD BOSS HANDLERS (server-authoritative)
      // ──────────────────────────────────────────────────────
      case 'sv_worldboss_spawn': {
        // Client requests a world boss spawn (via console spawnWorldBoss() or
        //   the auto-timer that fires once enough players are online).
        if (!player.gameId) break;
        const g = games.get(player.gameId);
        if (!g) break;
        // Already one active?
        if (g.worldBoss && g.worldBoss.spawned) {
          send(ws, { type:'sv_worldboss_reject', reason:'active', activeId: g.worldBoss.id, name: g.worldBoss.name });
          break;
        }
        // Cooldown after a kill
        if (g.worldBossLastDespawnAt && (Date.now() - g.worldBossLastDespawnAt) < WORLD_BOSS_RESPAWN_MS) {
          const remain = Math.ceil((WORLD_BOSS_RESPAWN_MS - (Date.now() - g.worldBossLastDespawnAt)) / 1000);
          send(ws, { type:'sv_worldboss_reject', reason:'cooldown', remainSec: remain });
          break;
        }
        // Pick def — by id if provided, else random
        let def = null;
        if (data.bossId && WORLD_BOSS_BY_ID[data.bossId]) {
          def = WORLD_BOSS_BY_ID[data.bossId];
        } else if (typeof data.idx === 'number' && data.idx >= 0 && data.idx < WORLD_BOSS_DEFS.length) {
          def = WORLD_BOSS_DEFS[data.idx];
        } else {
          def = WORLD_BOSS_DEFS[Math.floor(Math.random() * WORLD_BOSS_DEFS.length)];
        }
        const spawned = spawnWorldBoss(g, def);
        if (!spawned) send(ws, { type:'sv_worldboss_reject', reason:'failed' });
        break;
      }

      case 'sv_worldboss_hit': {
        if (!player.gameId) break;
        const g = games.get(player.gameId);
        if (!g) break;
        const wb = g.worldBoss;
        if (!wb || !wb.spawned) break;
        if (wb.hp <= 0) break;
        // Player must be in the boss's zone — prevents cross-zone hit exploits
        if (player.zone !== wb.zone) break;
        // Cap damage (anti-cheat) — world bosses can take big hits but not absurd ones
        const dmg = Math.min(Math.max(0, data.dmg|0), 999999);
        if (dmg <= 0) break;
        wb.hp = Math.max(0, wb.hp - dmg);
        wb.lastHitAt = Date.now();
        // Track contributor by name (sum total dmg)
        wb.contributors[player.name] = (wb.contributors[player.name] || 0) + dmg;
        // Broadcast HP update to the zone
        broadcastToZone(g.id, wb.zone, {
          type: 'sv_worldboss_hp',
          id: wb.id,
          hp: wb.hp,
          maxHp: wb.maxHp,
          phase: wb.phase,
          dmg,
          hitter: player.name,
        });
        // Phase transitions
        const pct = wb.hp / wb.maxHp;
        const oldPhase = wb.phase;
        if (wb.phase === 1 && pct <= 0.75) wb.phase = 2;
        else if (wb.phase === 2 && pct <= 0.50) wb.phase = 3;
        else if (wb.phase === 3 && pct <= 0.25) wb.phase = 4;
        if (wb.phase !== oldPhase) {
          broadcastToZone(g.id, wb.zone, {
            type: 'sv_worldboss_phase',
            id: wb.id,
            phase: wb.phase,
            bossName: wb.name,
          });
        }
        // Death
        if (wb.hp <= 0) {
          despawnWorldBoss(g, true, player.name, +wb.x.toFixed(2), +wb.z.toFixed(2));
        }
        break;
      }

      case 'sv_set_depth': {
        // v93.0 phase 3.3/4.2 — Client signals descent + modifier roll.
        // Server bumps depth, applies server-coord mods, regenerates enemies.
        if (!player.gameId || !player.zone) break;
        if (data.zone !== 'convergence') break;
        const g = games.get(player.gameId);
        if (!g) break;
        const zone = g.zones['convergence'];
        if (!zone) break;
        const newDepth = Math.max(1, Math.min(50, parseInt(data.depth, 10) || 1));
        const oldDepth = zone.convergenceDepth || 1;
        // Accept the mod IDs (validated by name match)
        const modIds = Array.isArray(data.modIds) ? data.modIds.slice(0, 5) : [];
        const hasMod = (id) => modIds.includes(id);

        // a233 — CO-OP guard. The Convergence zone is SHARED by everyone in the
        //   game. A late-joiner's client always rolls a "fresh entry at Depth 1"
        //   on zone-load and fires sv_set_depth — which previously regenerated the
        //   entire zone at Depth 1, wiping the in-progress deeper run for everyone
        //   already inside. Rule: a request may only ESTABLISH a run (no one in
        //   yet) or ADVANCE it (deeper than the current live depth). A request at
        //   a depth <= the live depth from someone who isn't actually driving the
        //   run is treated as "I'm joining" — we just (re)send them the live run
        //   state so they sync to the shared seed/depth/mods, and do NOT regen.
        const playersHere = getPlayersInZone(g.id, 'convergence').length;
        const runInProgress = !!zone._runEstablished;
        const isAdvance = newDepth > oldDepth;
        if (runInProgress && !isAdvance) {
          // Joining / re-rolling at or below the live depth → adopt live run.
          send(ws, buildRunState(zone, 'convergence'));
          console.log(`[convergence] ${player.name} requested depth ${newDepth} but live run is at ${oldDepth} (players=${playersHere}) — synced to live run, no regen.`);
          break;
        }

        // This request establishes or advances the shared run. The DRIVER's client
        //   seed is adopted as the authoritative run seed on a fresh establish so
        //   the driver's already-built local map matches the server; on a pure
        //   advance we keep the existing run seed (continuity within a run).
        const _seedBefore = zone.runSeed;
        if (!runInProgress && typeof data.seed === 'number' && isFinite(data.seed)) {
          zone.runSeed = (data.seed & 0x7fffffff) || zone.runSeed;
        }
        const seedChanged = zone.runSeed !== _seedBefore;   // a599 — a new seed is a new maze: mobs must be re-placed
        zone._runEstablished = true;

        // Skip if depth AND mods both unchanged
        const sameMods = JSON.stringify(modIds.slice().sort()) === JSON.stringify((zone.activeModIds||[]).slice().sort());
        if (newDepth === oldDepth && sameMods && !seedChanged) break;

        zone.convergenceDepth = newDepth;
        zone.activeModIds = modIds;

        // v93.0 phase 4.2 — Compute stat multipliers from depth + mods
        const depthMul = 1.0 + 0.5 * (newDepth - 1);
        const baseScale = ZONE_SCALE['convergence'] || 2.0;
        const hpMul = hasMod('vital') ? 2.0 : 1.0;
        const atkMul = hasMod('brutal') ? 1.75 : 1.0;
        const rewardMul = hasMod('bounty') ? 3.0 : 1.0;
        // Hardened Echo: +50% dmg reduction (separate field)
        const extraDR = hasMod('hardened_echo') ? 0.5 : 0;
        // Frenzied: 60% faster attacks — multiplied into spd (lower attackTimer cooldown isn't a stat so we boost spd)
        // Note: server doesn't tick enemy AI for combat; client AI handles. But Frenzied
        // affects movement/positioning indirectly via spd.
        // We pass it through via a custom field; client AI honors it if present.
        const frenzyMul = hasMod('frenzied') ? 1.6 : 1.0;

        // Density: 3x enemy count
        // a599 — spawns come from this run's maze at the new depth (Density = 3 per spot)
        const procSpawns = generateConvergenceSpawns(newDepth, zone.runSeed, hasMod('density') ? 3 : 1);
        if (hasMod('density')) console.log(`[convergence] Density active: ${procSpawns.length} enemies (3x base)`);

        zone.enemies = procSpawns.map((s, i) => {
          const st = ENEMY_STATS[s.type] || ENEMY_STATS.soldier;
          const effectiveScale = baseScale * depthMul;
          // a206 — floor under-tier convergence mobs to the pool tier (see convBaseHp)
          const _baseHp = convBaseHp(s.type, st.hp);
          return {
            id: i,
            type: s.type,
            x: s.tx * TILE,
            z: s.tz * TILE,
            spawnX: s.tx * TILE,
            spawnZ: s.tz * TILE,
            hp: Math.round(_baseHp * effectiveScale * hpMul),
            maxHp: Math.round(_baseHp * effectiveScale * hpMul),
            atk: Math.round(convBaseAtk(s.type, st.atk) * effectiveScale * atkMul),   // a609 — attack floor too
            spd: st.spd * frenzyMul,
            aggroRange: st.aggroRange,
            reward: Math.round(st.reward * effectiveScale * rewardMul),
            expR: Math.round(st.expR * effectiveScale),
            dmgReduction: Math.min(0.85, (st.dmgReduction || 0) + extraDR),
            active: true,
            aggroed: false,
            attackTimer: Math.floor(Math.random() * 60),
            respawnTimer: 0,
            // v93.0 phase 4.2 — Track which mods affect this enemy for client display
            _convergenceMods: modIds,
          };
        });
        // v93.0-a27 — Boss reset for new depth + scaling + respawn broadcast.
        // Previous bug: server set spawned=false but never told the client. Client kept
        // local boss alive, hit it, but server dropped hits ("if (!b.spawned) break").
        // Damage numbers popped client-side, server HP never decreased.
        // a218 — Bofis RED ALERT: Convergence bosses randomly healed to full
        //   mid-fight. CAUSE: this block reset zone.boss.hp = maxHp whenever
        //   sv_set_depth ran with the depth unchanged but the MODS changed
        //   (a re-roll, a second player entering and rolling, a reconnect, etc.)
        //   — refilling an in-progress boss. FIX: only refill the boss when the
        //   DEPTH actually changes. A same-depth mod update still rescales
        //   enemies but must NEVER touch the live boss HP.
        if (zone.boss && newDepth !== oldDepth) {
          // Scale max HP for depth + Vital modifier
          const _baseBossHp = (ZONE_BOSS_HP['convergence'] || {hp: 2000000}).hp;
          const _scaledMaxHp = Math.round(_baseBossHp * depthMul * hpMul);
          zone.boss.maxHp = _scaledMaxHp;
          zone.boss.hp = _scaledMaxHp;
          zone.boss.spawned = true; // mark as actively in world for the new depth
          zone.boss.phase = 1;
          // Broadcast a fresh boss-spawned event so all clients re-sync
          broadcastToZone(g.id, 'convergence', {
            type: 'sv_boss_spawned',
            zone: 'convergence',
            bossName: zone.boss.name,
            hp: zone.boss.hp,
            maxHp: zone.boss.maxHp,
          });
          console.log(`[convergence] Boss reset for Depth ${newDepth}: ${_scaledMaxHp.toLocaleString()} HP (x${depthMul.toFixed(2)} depth, x${hpMul.toFixed(2)} vital)`);
        } else if (zone.boss) {
          console.log(`[convergence] Same-depth mod update at Depth ${newDepth} — boss HP left at ${(zone.boss.hp||0).toLocaleString()} (NOT refilled).`);
        }
        console.log(`[convergence] Depth ${oldDepth} -> ${newDepth}. Mods: [${modIds.join(',')||'none'}]. ${zone.enemies.length} enemies. hpMul=${hpMul} atkMul=${atkMul} dr+${extraDR}`);
        // a233 — CO-OP: tell every player in the zone the new authoritative seed +
        //   depth + mods so they all rebuild the IDENTICAL layout for this depth.
        broadcastToZone(g.id, 'convergence', buildRunState(zone, 'convergence'));
        broadcastToZone(g.id, 'convergence', {
          type: 'sv_zone_snapshot',
          zone: 'convergence',
          ids: zone.enemies.map(e => e.id),
          xs: zone.enemies.map(e => e.x),
          zs: zone.enemies.map(e => e.z),
          hps: zone.enemies.map(e => e.hp),
          maxhps: zone.enemies.map(e => e.maxHp),
          types: zone.enemies.map(e => e.type),
          acts: zone.enemies.map(e => e.active ? 1 : 0),
          rots: zone.enemies.map(() => 0),
        });
        break;
      }

      case 'sv_boss_spawned': {
        // Client tells server boss spawned in their zone
        if (!player.gameId || !player.zone) break;
        const g = games.get(player.gameId);
        if (!g) break;
        const zone = g.zones[player.zone];
        if (!zone || !zone.boss) break;
        if (!zone.boss.spawned) {
          zone.boss.spawned = true;
          // a226 — ONLY refill if the boss is actually dead. The client re-sends
          //   sv_boss_spawned in several situations (proximity re-trigger, local
          //   mesh re-spawn, reconnect). If the server's spawned flag happened to
          //   be false at that moment, this used to slam hp back to maxHp mid-
          //   fight — the random "Archon heals to full" bug. A live boss keeps
          //   its current HP.
          if (zone.boss.hp <= 0) {
            zone.boss.hp = zone.boss.maxHp;
            zone.boss.phase = 1;
          }
          // Announce to zone
          broadcastToZone(g.id, player.zone, {
            type: 'sv_boss_spawned',
            zone: player.zone,
            bossName: zone.boss.name,
            hp: zone.boss.hp,
            maxHp: zone.boss.maxHp,
          });
        }
        break;
      }

      // ── a721 — GROUND DROPS (see _GD) ──
      case 'sv_gdrop': {
        const zone = _gdZoneOk(data.zone) ? data.zone : player.zone;
        if (_gdZoneOk(zone)) player.zone = zone;   // the client's own zone is the freshest (solo players send no state packets)
        const e = _gdClean(data.e);
        if (!_gdZoneOk(zone) || !e || !isFinite(+data.x) || !isFinite(+data.z)) { if (e) send(ws, { type:'sv_gback', e }); break; }
        const scope = _gdScope(player), b = _gdBucket(scope, zone, true);
        if (b.size >= _GD_CAP) {   // full: the oldest item on the floor makes room
          const old = b.keys().next().value; b.delete(old);
          _gdSend(scope, zone, { type:'sv_ggone', gid:old, zone });
        }
        const d = { gid:'g' + (++_gdSeq), zone, x:+(+data.x).toFixed(2), z:+(+data.z).toFixed(2), e, by:player.name || '', t:Date.now() };
        b.set(d.gid, d);
        _gdSend(scope, zone, Object.assign({ type:'sv_gdrop' }, _gdPub(d)));
        break;
      }
      case 'sv_gpick': {
        const zone = _gdZoneOk(data.zone) ? data.zone : player.zone;
        if (_gdZoneOk(zone)) player.zone = zone;   // the client's own zone is the freshest (solo players send no state packets)
        if (!_gdZoneOk(zone) || typeof data.gid !== 'string') break;
        const scope = _gdScope(player), b = _gdBucket(scope, zone, false);
        const d = b && b.get(data.gid);
        if (!d) { send(ws, { type:'sv_ggone', gid:data.gid, zone }); break; }
        b.delete(d.gid);
        send(ws, { type:'sv_gtake', gid:d.gid, zone, e:d.e, by:d.by });
        _gdSend(scope, zone, { type:'sv_ggone', gid:d.gid, zone, who:player.name || '' });
        break;
      }
      case 'sv_gsnap_req': {
        const zone = _gdZoneOk(data.zone) ? data.zone : player.zone;
        if (_gdZoneOk(zone)) player.zone = zone;   // the client's own zone is the freshest (solo players send no state packets)
        if (_gdZoneOk(zone)) _gdSnapshot(ws, player, zone);
        break;
      }

      case 'sv_zone_announce':
        // Intentionally ignored — sv_enter_zone already sends sv_player_entered
        // and sv_zone_entered_announce. Handling this separately caused duplicate chat messages.
        break;

      case 'sv_vfx': {
        // Lightweight VFX relay — forwards skill/spell VFX packets to all other players
        // in the same zone. Belt-and-suspenders backup for PeerJS VFX broadcasts so VFX
        // still reaches teammates if the P2P link is flaky or missing.
        if (!player.gameId || !player.zone) break;
        // Basic size guard so we never relay oversized or spammed packets
        if (typeof data !== 'object' || !data.vt) break;
        const relay = {
          type: 'sv_vfx',
          vt: String(data.vt).slice(0, 40),
          zone: player.zone,
          from: player.name,
        };
        // Allow a small fixed set of numeric/string fields only
        ['px','pz','tx','tz','dx','dz','col','skId','wtype','r','br','t','heavy'].forEach(k=>{
          if (data[k] !== undefined) relay[k] = data[k];
        });
        broadcastToZone(player.gameId, player.zone, relay, ws);
        break;
      }

      // ══════════════════════════════════════════════════════════
      // GUILD SYSTEM
      // ══════════════════════════════════════════════════════════
      case 'guild_create': {
        if(!player.name){ send(ws,{type:'guild_err',msg:'Not logged in.'}); break; }
        const already = findPlayerGuild(player.name);
        if(already){ send(ws,{type:'guild_err',msg:'You are already in a guild.'}); break; }
        const gname = (data.name||'').trim().slice(0,32);
        const gtag = (data.tag||'').trim().toUpperCase().slice(0,4);
        if(gname.length < 3 || gtag.length < 2){
          send(ws,{type:'guild_err',msg:'Name must be 3+ chars, tag must be 2-4 chars.'}); break;
        }
        // Name/tag uniqueness
        const gid = gname.toLowerCase().replace(/[^a-z0-9]/g,'');
        if(!gid){ send(ws,{type:'guild_err',msg:'Name must contain letters/numbers.'}); break; }
        if(guilds[gid]){ send(ws,{type:'guild_err',msg:'A guild with that name exists.'}); break; }
        for(const g of Object.values(guilds)){
          if(g.tag === gtag){ send(ws,{type:'guild_err',msg:'That tag is taken.'}); break; }
        }
        // Create
        guilds[gid] = {
          name: gname,
          tag: gtag,
          level: 1,
          xp: 0,
          leader: player.name,
          members: {[player.name]: Date.now()},
          motd: '',
          created: Date.now()
        };
        flushGuilds();
        send(ws,{type:'guild_created', guildId:gid, guild:guilds[gid]});
        console.log(`[guild] ${player.name} created guild "${gname}" [${gtag}]`);
        break;
      }

      case 'guild_list': {
        // Return sorted list (by member count, then by level)
        const list = Object.entries(guilds).map(([id,g])=>({
          id, name:g.name, tag:g.tag, level:g.level||1,
          memberCount: Object.keys(g.members||{}).length,
          leader: g.leader
        })).sort((a,b)=>{
          if(b.level !== a.level) return b.level - a.level;
          return b.memberCount - a.memberCount;
        });
        send(ws,{type:'guild_list', guilds:list});
        break;
      }

      case 'guild_join': {
        if(!player.name){ send(ws,{type:'guild_err',msg:'Not logged in.'}); break; }
        const already = findPlayerGuild(player.name);
        if(already){ send(ws,{type:'guild_err',msg:'You are already in a guild.'}); break; }
        const gid = (data.guildId||'').toLowerCase();
        const g = guilds[gid];
        if(!g){ send(ws,{type:'guild_err',msg:'Guild not found.'}); break; }
        if(!g.members) g.members = {};
        g.members[player.name] = Date.now();
        flushGuilds();
        send(ws,{type:'guild_joined', guildId:gid, guild:g});
        broadcastGuildUpdate(gid);
        broadcastGuildChat(gid, '[SYSTEM]', `${player.name} joined the guild.`);
        console.log(`[guild] ${player.name} joined "${g.name}"`);
        break;
      }

      case 'guild_leave': {
        if(!player.name){ send(ws,{type:'guild_err',msg:'Not logged in.'}); break; }
        const found = findPlayerGuild(player.name);
        if(!found){ send(ws,{type:'guild_err',msg:'You are not in a guild.'}); break; }
        const {id, guild} = found;
        delete guild.members[player.name];
        // If leader leaves, promote earliest-joined member (or delete if empty)
        if(guild.leader === player.name){
          const remaining = Object.entries(guild.members||{}).sort((a,b)=>a[1]-b[1]);
          if(remaining.length === 0){
            delete guilds[id];
            console.log(`[guild] "${guild.name}" disbanded (leader left, no members).`);
          } else {
            guild.leader = remaining[0][0];
            console.log(`[guild] ${guild.leader} is new leader of "${guild.name}"`);
          }
        }
        flushGuilds();
        send(ws,{type:'guild_left'});
        if(guilds[id]){
          broadcastGuildUpdate(id);
          broadcastGuildChat(id, '[SYSTEM]', `${player.name} left the guild.`);
        }
        break;
      }

      case 'guild_chat_send': {
        if(!player.name){ break; }
        const found = findPlayerGuild(player.name);
        if(!found) break;
        const msg = (data.msg||'').trim().slice(0,200);
        if(!msg) break;
        broadcastGuildChat(found.id, player.name, msg);
        break;
      }

      case 'guild_info': {
        // Return current user's guild info (on login)
        if(!player.name) break;
        const found = findPlayerGuild(player.name);
        if(found) send(ws,{type:'guild_info', guildId:found.id, guild:found.guild});
        else send(ws,{type:'guild_info', guildId:null, guild:null});
        break;
      }

      case 'guild_set_motd': {
        if(!player.name) break;
        const found = findPlayerGuild(player.name);
        if(!found){ send(ws,{type:'guild_err',msg:'Not in a guild.'}); break; }
        if(found.guild.leader !== player.name){
          send(ws,{type:'guild_err',msg:'Only the leader can set MOTD.'}); break;
        }
        found.guild.motd = (data.motd||'').slice(0, 200);
        flushGuilds();
        broadcastGuildUpdate(found.id);
        break;
      }

      case 'guild_award_xp': {
        // Solo-mode XP request — client tells server how much XP their kill earned.
        // Server validates player is in a guild, then adds XP (with a safety cap).
        if(!player.name) break;
        const found = findPlayerGuild(player.name);
        if(!found) break;
        // Rate-limit: max 500 XP per request, and track per-connection total to prevent spam
        const requestedXp = Math.min(500, Math.max(0, Math.floor(data.amount||0)));
        if(requestedXp <= 0) break;
        // Per-connection rate limit: max 5000 XP per 10 seconds
        player._guildXpWindow = player._guildXpWindow || {start:Date.now(), total:0};
        const now = Date.now();
        if(now - player._guildXpWindow.start > 10000){
          player._guildXpWindow = {start:now, total:0};
        }
        if(player._guildXpWindow.total + requestedXp > 5000){
          break; // silently drop — likely spam/cheat
        }
        player._guildXpWindow.total += requestedXp;
        const oldLvl = found.guild.level || 1;
        awardGuildXp(player.name, requestedXp);
        // Send authoritative XP sync back to the requester (cheap — no broadcast needed)
        send(ws, {type:'guild_xp_sync', xp:found.guild.xp, level:found.guild.level||1});
        // If they leveled up, broadcast full guild state to ALL members (level changes affect everyone's perks)
        const newLvl = found.guild.level || 1;
        if(newLvl > oldLvl){
          broadcastGuildUpdate(found.id);
        }
        break;
      }
    }
  });

  ws.on('close',  () => removePlayer(ws));
  ws.on('error',  () => removePlayer(ws));
});

// Clean up empty or abandoned games every 2 minutes
setInterval(()=>{
  const now = Date.now();
  games.forEach((g, id) => {
    // Delete if: no players left, or older than 6 hours, or inactive for 30 min with 0 players
    const empty = g.players.length === 0;
    const old   = now - g.createdAt > 6*60*60*1000;
    const stale = empty && (now - g.createdAt > 30*60*1000);
    if(old || stale) games.delete(id);
  });
  broadcastGameList();
}, 2*60*1000);

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => console.log('Empire 2 server running on port ' + PORT));
